/* Per-object-kind checks of the GDI handle value and its cell in PEB->GdiSharedHandleTable.
 * Every kind in gh.h gets the same set of tests, generated by GH_KINDS. */
#include "gh.h"

static int gh_gui(HANDLE proc, int flags) { return U(GetGuiResources) ? (int)U(GetGuiResources)(proc, flags) : -1; }

/* handle value layout: the 32-bit value is (reuse byte << 24) | (type << 16) | index; the high dword is zero or the
 * sign extension of bit 31 (see t_decode). */
static void t_decode(const struct gh_kind *k) {
    GH_NEED();
    GH_MAKE(h, k);
    ULONG_PTR v = (ULONG_PTR)h;
    /* the handle is a 32-bit value: the high dword is either zero (handles that pass through gdi32's cache) or the sign
       extension of bit 31 (reuse byte >= 0x80, handles straight from the kernel) */
    CHECKF(v == (ULONG_PTR)(LONG_PTR)(int)(unsigned)v || (v >> 32) == 0, "%s handle %p is not a 32-bit value", k->name, h);
    CHECKF(GH_TYPE7(h) == k->type7, "%s handle %p type bits 0x%x want 0x%x", k->name, h, GH_TYPE7(h), k->type7);
    CHECKF(!GH_STOCKED(h), "%s: stock bit set on a fresh object %p", k->name, h);
    CHECKF(GH_IDX(h) < GH_CELLS, "%s idx 0x%x", k->name, GH_IDX(h));
    if (GH_IDX(h) == 0) t_note("%s got table index 0", k->name);
    t_info("%s handle=%p idx=0x%x type=0x%02x uniq=0x%02x", k->name, h, GH_IDX(h), GH_TYPE7(h), GH_UNIQ(h));
    k->rm(h);
}

static void t_cell(const struct gh_kind *k) {
    GH_NEED();
    GH_MAKE(h, k);
    struct gh_cell c;
    if (!gh_cell_of(h, &c)) { CHECKF(0, "%s: cell for %p unreadable", k->name, h); k->rm(h); return; }
    /* ENTRYOBJ::hSetup stores `index | 0xffffffffff000000` (with the reuse byte in bits 16..23) in the
     * first qword: a kernel-range value that is not a real object pointer. */
    CHECKF(c.q0 >= GH_KERNEL_FLOOR, "%s q0=0x%llx not in kernel range", k->name, c.q0);
    CHECKF(c.q0 == (0xffffffffff000000ull | ((unsigned long long)GH_UNIQ(h) << 16) | GH_IDX(h)),
           "%s q0=0x%llx for handle %p", k->name, c.q0, h);
    /* Handle layout: the entry is HIWORD(handle), low byte = type (| 0x80 stock), high byte = reuse byte. */
    CHECKF(c.upper == GH_HIWORD(h), "%s upper=0x%04x HIWORD(h)=0x%04x", k->name, c.upper, GH_HIWORD(h));
    CHECKF((c.upper >> 8) == GH_UNIQ(h), "%s cell+0xd=0x%02x uniq=0x%02x", k->name, c.upper >> 8, GH_UNIQ(h));
    if (k->objt >= 0) CHECKF(c.objt == k->objt, "%s objt=0x%02x want 0x%02x", k->name, c.objt, k->objt);
    else t_note("%s objt=0x%02x (type bits 0x%02x)", k->name, c.objt, k->type7);
    /* every gdi32full validator requires (owner & ~1) == gW32PID for a private object */
    CHECKF((c.owner & ~1u) == GH_PID(), "%s owner=0x%x pid=%u", k->name, c.owner, GH_PID());
    if (k->puser == 1) CHECKF(c.puser != 0, "%s pUser is NULL", k->name);
    else if (k->puser == 0) CHECKF(c.puser == 0, "%s pUser=0x%llx", k->name, c.puser);
    else t_note("%s pUser=0x%llx flags=0x%02x", k->name, c.puser, c.flags);
    if (c.puser) CHECKF(c.puser < GH_KERNEL_FLOOR, "%s pUser 0x%llx is a kernel address", k->name, c.puser);
    k->rm(h);
}

static void t_objtype(const struct gh_kind *k) {
    GH_NEED();
    GH_MAKE(h, k);
    DWORD t = U(GetObjectType)((HGDIOBJ)h);
    CHECKF(t == k->objtype, "%s GetObjectType=%lu want %lu", k->name, t, k->objtype);
    k->rm(h);
}

static void t_delete_clears(const struct gh_kind *k) {
    GH_NEED();
    GH_MAKE(h, k);
    struct gh_cell before, after;
    if (!gh_cell_of(h, &before)) { k->rm(h); t_skip("cell unreadable"); return; }
    unsigned idx = GH_IDX(h);
    if (gh_cached_kind(k)) gh_cache_fill(k);
    k->rm(h);
    if (gh_cached_kind(k)) {
        /* The first DeleteObject of a solid brush or rectangular region only retires the object: its cell stays allocated
           with its client block, and repeating the DeleteObject on the handle releases the cell (which one of the repeats
           does depends on what the handle caches already hold, so repeat up to three times). */
        struct gh_cell cc;
        for (int rep = 0; rep < 3 && gh_read(idx, &cc) && cc.objt != 0 && cc.upper == GH_HIWORD(h); rep++) U(DeleteObject)(h);
    }
    if (!gh_read(idx, &after)) { CHECK(0); return; }
    if (gh_cached_kind(k) && after.objt != 0 && (after.owner & ~1u) == GH_PID()) {
        /* observed for rectangular regions: the cell stays allocated for the region cache whatever is deleted around it */
        t_skip("%s: the deleted object's cell is still held by the handle cache (objt 0x%02x)", k->name, after.objt);
        return;
    }
    /* HANDLELOCK::vUnlockAndRelease: Objt = 0, pUser = 0, owner = owner & 1; the slot goes onto the
     * free list unless the same slot was re-used meanwhile (not possible on this thread). */
    CHECKF(after.objt == 0, "%s objt after delete = 0x%02x", k->name, after.objt);
    CHECKF(after.puser == 0, "%s pUser after delete = 0x%llx", k->name, after.puser);
    CHECKF((after.owner & ~1u) == 0, "%s owner after delete = 0x%x", k->name, after.owner);
    if ((after.q0 >> 32) != 0) t_note("%s q0 after delete = 0x%llx (free-list link expected)", k->name, after.q0);
    /* the reuse byte survives a free so the next allocation of the slot can bump it */
    CHECKF((after.upper >> 8) == (before.upper >> 8), "%s reuse byte 0x%02x -> 0x%02x", k->name, before.upper >> 8, after.upper >> 8);
}

static void t_stale(const struct gh_kind *k) {
    GH_NEED();
    GH_MAKE(h, k);
    if (gh_cached_kind(k)) gh_cache_fill(k);
    k->rm(h);
    /* NtGdiDeleteObjectApp finds Objt 0 / no lockable object for the stale handle and returns 0 for every type except
     * palettes: for a palette handle whose object is gone it answers TRUE. */
    ULONG_PTR r = UN(NtGdiDeleteObjectApp) ? UN(NtGdiDeleteObjectApp)((HANDLE)h) : 1;
    ULONG_PTR want = (k->type7 == 0x08) ? 1 : 0;
    if (UN(NtGdiDeleteObjectApp)) CHECKF((r & 0xff) == want, "%s: NtGdiDeleteObjectApp(stale) = %llu want %llu", k->name, (unsigned long long)r, (unsigned long long)want);
    if (k->type7 == 0x01 && UN(NtGdiGetDCObject))
        CHECK(UN(NtGdiGetDCObject)((HANDLE)h, 0x100000) == NULL);
    DWORD t = U(GetObjectType)((HGDIOBJ)h);
    t_note("%s GetObjectType(stale)=%lu", k->name, t);
}

static void t_getentry(const struct gh_kind *k) {
    GH_NEED();
    REQUIRE(GHN(NtGdiGetEntry));
    GH_MAKE(h, k);
    struct gh_cell a, b;
    if (!gh_cell_of(h, &a)) { k->rm(h); t_skip("cell unreadable"); return; }
    memset(&b, 0xA5, sizeof b);
    /* NtGdiGetEntry: DecodeIndex(index) -> _ENTRY, copies 3 qwords to the caller */
    LONG st = GHN(NtGdiGetEntry)(GH_IDX(h), &b);
    CHECKF(st == 0, "NtGdiGetEntry status 0x%lx", st);
    CHECK(b.q0 == a.q0);
    CHECK(b.upper == a.upper);
    CHECK(b.objt == a.objt);
    CHECK(b.puser == a.puser);
    CHECK((b.owner & ~1u) == (a.owner & ~1u));
    k->rm(h);
}

static void t_gui_count(const struct gh_kind *k) {
    if (k->nh < 0) { t_skip("handle count not asserted for %s", k->name); return; }
    GH_NEED();
    REQUIRE(U(GetGuiResources));
    HGDIOBJ held[GH_CACHE_PROBE]; int nheld = 0;
    if (gh_cached_kind(k)) nheld = gh_cache_hold(k, held);      /* empty cache: the create below allocates a fresh cell */
    int b0 = gh_gui(GetCurrentProcess(), 0);
    GH_MAKE(h, k);
    int b1 = gh_gui(GetCurrentProcess(), 0);
    CHECKF(b1 - b0 == k->nh, "%s: GR_GDIOBJECTS %d -> %d", k->name, b0, b1);
    for (int i = 0; i < nheld; i++) k->rm(held[i]);             /* fills the cache */
    int bm = gh_gui(GetCurrentProcess(), 0);
    k->rm(h);
    int b2 = gh_gui(GetCurrentProcess(), 0);
    CHECKF(b2 == bm - k->nh, "%s: GR_GDIOBJECTS after delete %d want %d", k->name, b2, bm - k->nh);
    if (!nheld) CHECKF(b2 == b0, "%s: GR_GDIOBJECTS after delete %d want %d", k->name, b2, b0);
    int pk = gh_gui(GetCurrentProcess(), 2);
    CHECKF(pk >= b1, "%s: peak %d < %d", k->name, pk, b1);
}

static void t_distinct(const struct gh_kind *k) {
    GH_NEED();
    HGDIOBJ hs[16]; int n = 0;
    for (; n < 16; n++) { hs[n] = k->mk(); if (!hs[n]) break; }
    if (n < 2) { t_skip("cannot create several %s", k->name); for (int i = 0; i < n; i++) k->rm(hs[i]); return; }
    for (int i = 0; i < n; i++) {
        struct gh_cell c;
        for (int j = i + 1; j < n; j++) CHECKF(GH_IDX(hs[i]) != GH_IDX(hs[j]), "%s: live objects %d,%d share table index 0x%x", k->name, i, j, GH_IDX(hs[i]));
        for (int j = i + 1; j < n; j++) CHECKF(hs[i] != hs[j], "%s: two live objects share handle %p", k->name, hs[i]);
        if (gh_cell_of(hs[i], &c)) CHECKF(c.objt != 0, "%s: live cell %d empty", k->name, i);
    }
    for (int i = 0; i < n; i++) k->rm(hs[i]);
}

#define GEN(id) \
    TEST(gdi_handle_table_##id##_handle_decode)   { t_decode(&gk_##id); } \
    TEST(gdi_handle_table_##id##_cell_fields)     { t_cell(&gk_##id); } \
    TEST(gdi_handle_table_##id##_get_object_type) { t_objtype(&gk_##id); } \
    TEST(gdi_handle_table_##id##_delete_clears)   { t_delete_clears(&gk_##id); } \
    TEST(gdi_handle_table_##id##_stale_handle)    { t_stale(&gk_##id); } \
    TEST(gdi_handle_table_##id##_nt_get_entry)    { t_getentry(&gk_##id); } \
    TEST(gdi_handle_table_##id##_gui_count)       { t_gui_count(&gk_##id); } \
    TEST(gdi_handle_table_##id##_distinct_live)   { t_distinct(&gk_##id); }
GH_KINDS(GEN)

/* GetDC(NULL) hands out a cached DC owned by USER's DC cache entry; only look at it, release it through ReleaseDC. */
TEST(gdi_handle_table_dc_getdc_handle_decode)   { t_decode(&gk_dc_getdc); }
TEST(gdi_handle_table_dc_getdc_cell_fields)     { t_cell(&gk_dc_getdc); }
TEST(gdi_handle_table_dc_getdc_get_object_type) { t_objtype(&gk_dc_getdc); }
TEST(gdi_handle_table_dc_getdc_nt_get_entry)    { t_getentry(&gk_dc_getdc); }
